  const r = await fetch('/api/Users', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({email:'probe1@example.test', password:'Passw0rd!p1', passwordRepeat:'Passw0rd!p1', securityQuestion:{id:1}, securityAnswer:'x'})});
  const j = await r.json();
  const l = await fetch('/rest/user/login', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({email:'probe1@example.test', password:'Passw0rd!p1'})});
  const lj = await l.json();
  const tok = lj.authentication.token;
  const h = {'Content-Type':'application/json', Authorization:'Bearer '+tok};
  const bid = lj.authentication.bid;
  const basket = await (await fetch('/rest/basket/'+bid, {headers:h})).json();
  const search = await (await fetch('/rest/products/search?q=', {headers:{}})).json();
  const names = search.data.slice(0,16).map(p=>[p.id,p.name,p.price]);
  const deliv = await (await fetch('/api/Deliverys')).json();
  return JSON.stringify({status:r.status, user:j.data && {id:j.data.id, email:j.data.email, role:j.data.role}, loginStatus:l.status, bid, basketItems: basket.data && basket.data.Products, names, deliv: deliv.data.map(d=>[d.id,d.name,d.price,d.deluxePrice])});
}

