  const tok = l.authentication.token, bid = l.authentication.bid;
  const A = {'Authorization':'Bearer '+tok};
  const bi = await post('/api/BasketItems', {ProductId:3, BasketId:String(bid), quantity:1}, A);
  out.addItemStatus = bi.status; out.addItem = (await bi.text()).slice(0,200);
  const addr = await post('/api/Addresss', {fullName:'Test Customer', mobileNum:501234567, zipCode:'01001', streetAddress:'1 Khreshchatyk Street', city:'Kyiv', state:'Kyiv', country:'Ukraine'}, A);
  out.addrStatus = addr.status; out.addr = (await addr.text()).slice(0,300);
  const card = await post('/api/Cards', {fullName:'Test Customer', cardNum:4111111111111111, expMonth:12, expYear:2090}, A);
  out.cardStatus = card.status; out.card = (await card.text()).slice(0,300);
  const w = await fetch('/rest/wallet/balance', {headers:A}); out.walletGet = await w.text();
  return JSON.stringify(out);
}

