import { encode } from 'z85';

/**
 * Coupon codes of the shop: Z85 encoding of `<MMM><YY>-<NN>`, see test-cases/README.md.
 * The shop accepts a coupon only in the month that the coupon names. The month is taken
 * from the local time of the machine, the same as on the server (juice-shop-app.md, section 5).
 */
const COUPON_MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const YEAR_DIGITS = 2;
const PERCENT_DIGITS = 2;

export function buildCouponCode(month: Date, discountPercent: number): string {
  const monthName = COUPON_MONTHS[month.getMonth()];
  const year = String(month.getFullYear()).slice(-YEAR_DIGITS);
  const percent = String(discountPercent).padStart(PERCENT_DIGITS, '0');
  const text = `${monthName}${year}-${percent}`;
  const code = encode(text);
  if (code === null) {
    throw new Error(`Coupon text has a length that Z85 cannot encode: ${text}`);
  }
  return code;
}

/** A coupon of the current month. It is valid. */
export function currentMonthCoupon(discountPercent: number): string {
  return buildCouponCode(new Date(), discountPercent);
}

/** A coupon of the previous month. The shop rejects it as expired. */
export function previousMonthCoupon(discountPercent: number): string {
  const now = new Date();
  return buildCouponCode(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
}

