import { randomUUID } from 'node:crypto';

export interface CustomerCredentials {
  email: string;
  password: string;
}

const UNIQUE_PART_LENGTH = 8;
const WRONG_PASSWORD_SUFFIX = 'x';

/** A unique email and password for a new customer account. Each test gets its own customer. */
export function buildCustomerCredentials(): CustomerCredentials {
  const uniquePart = randomUUID().slice(0, UNIQUE_PART_LENGTH);
  return {
    email: `autotest-${uniquePart}@example.test`,
    password: `Passw0rd!${uniquePart}`,
  };
}

/** The password of the account with one more character. The shop must reject it. */
export function buildWrongPassword(correctPassword: string): string {
