import type { APIResponse } from '@playwright/test';

/** The shop wraps most payloads as `{ status, data }`. */
export interface ShopEnvelope<T> {
  status: string;
  data: T;
}

/** Reads the JSON body of a response. A failed response stops the test with the status and the body. */
export async function readJsonOrThrow<T>(response: APIResponse, action: string): Promise<T> {
  if (!response.ok()) {
    throw new Error(`${action} failed with status ${response.status()}: ${await response.text()}`);
  }
  return (await response.json()) as T;
}

