  authentication: {
    token: string;
    bid: number;
  };
}

export interface CustomerSession {
  token: string;
  basketId: number;
}

const SECURITY_QUESTION_ID = 1;
const SECURITY_ANSWER = 'autotest';

export class UserApi {
  constructor(private readonly request: APIRequestContext) {}

  /** Registers a customer and returns the id of the new account. */
  async register(credentials: CustomerCredentials): Promise<number> {
    const response = await this.request.post(API_ROUTES.users, {
      data: {
        email: credentials.email,
        password: credentials.password,
        passwordRepeat: credentials.password,
        securityQuestion: { id: SECURITY_QUESTION_ID },
        securityAnswer: SECURITY_ANSWER,
      },
    });
    const body = await readJsonOrThrow<ShopEnvelope<{ id: number }>>(response, 'Register a customer');
    return body.data.id;
  }

  /** Logs in through the API. Returns the token and the id of the basket of the customer. */
  async login(credentials: CustomerCredentials): Promise<CustomerSession> {
    const response = await this.request.post(API_ROUTES.login, {
      data: { email: credentials.email, password: credentials.password },
    });
    const body = await readJsonOrThrow<LoginResponse>(response, 'Log in a customer');
    return { token: body.authentication.token, basketId: body.authentication.bid };
  }
}

