import type { APIRequestContext } from '@playwright/test';
import { readJsonOrThrow, type ShopEnvelope } from '@/core/api/api-response';
import { API_ROUTES } from '@/utils/constants/routes';

interface ProductSearchItem {
  id: number;
  name: string;
}

export class ProductApi {
  constructor(private readonly request: APIRequestContext) {}

  /** Finds the id of a product by its exact name. Fails when the catalog has no such product. */
  async findIdByName(name: string): Promise<number> {
    const response = await this.request.get(`${API_ROUTES.productsSearch}?q=${encodeURIComponent(name)}`);
    const body = await readJsonOrThrow<ShopEnvelope<ProductSearchItem[]>>(response, 'Search a product');
    const product = body.data.find((item) => item.name === name);
    if (!product) {
      throw new Error(`Product not found in the catalog: ${name}`);
    }
    return product.id;
  }
}

