import type { APIRequestContext } from '@playwright/test';
import { readJsonOrThrow, type ShopEnvelope } from '@/core/api/api-response';
import { API_ROUTES } from '@/utils/constants/routes';
import type { Customer, SavedAddress, SavedCard } from '@/utils/types/shop-types';

/** Saved addresses, saved cards and the wallet of a customer. */
export class PaymentApi {
  constructor(private readonly request: APIRequestContext) {}

  private authorization(customer: Customer): Record<string, string> {
    return { Authorization: `Bearer ${customer.token}` };
  }

  async addAddress(customer: Customer, address: SavedAddress): Promise<void> {
    const response = await this.request.post(API_ROUTES.addresses, {
      headers: this.authorization(customer),
      data: {
        fullName: address.fullName,
        mobileNum: address.mobileNumber,
        zipCode: address.zipCode,
        streetAddress: address.streetAddress,
        city: address.city,
        state: address.state,
        country: address.country,
      },
    });
    await readJsonOrThrow<unknown>(response, 'Save an address');
  }

  /** Saves a card and returns its id. The id is the payment id of the card. */
  async addCard(customer: Customer, card: SavedCard): Promise<number> {
    const response = await this.request.post(API_ROUTES.cards, {
      headers: this.authorization(customer),
      data: {
        fullName: card.fullName,
        cardNum: card.cardNumber,
        expMonth: card.expiryMonth,
        expYear: card.expiryYear,
      },
    });
    const body = await readJsonOrThrow<ShopEnvelope<{ id: number }>>(response, 'Save a card');
    return body.data.id;
  }

  /** Adds money to the wallet. The shop accepts it only with a saved card of the customer. */
  async topUpWallet(customer: Customer, cardId: number, amount: number): Promise<void> {
    const response = await this.request.put(API_ROUTES.wallet, {
      headers: this.authorization(customer),
      data: { balance: amount, paymentId: String(cardId) },
    });
    await readJsonOrThrow<unknown>(response, 'Top up the wallet');
  }
}

