import type { Page } from '@playwright/test';
import { expectCount, expectVisible } from '@/utils/assertions/ui-assertions';

/** Common actions of every page: open a hash route, see a message or a title. */
export abstract class BasePage {
  constructor(protected readonly page: Page) {}

  protected async openRoute(route: string): Promise<void> {
    await this.page.goto(route, { waitUntil: 'domcontentloaded' });
  }

  async shouldSeeMessage(text: string): Promise<void> {
    await expectVisible(this.page.getByText(text, { exact: true }), `message "${text}"`);
  }

  async shouldNotSeeMessageContaining(fragment: string): Promise<void> {
    await expectCount(this.page.getByText(fragment), 0, `no message containing "${fragment}"`);
  }

  protected async shouldSeeTitle(title: string): Promise<void> {
    await expectVisible(this.page.getByRole('heading', { name: title }), `page title "${title}"`);
  }
}

