    await this.openRoute(UI_ROUTES.payment);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.payment.heading);
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    await expectVisible(this.cardRow(card), 'saved card');
  }

  async selectSavedCard(card: SavedCard): Promise<void> {
    await this.cardRow(card).getByRole('radio').click();
  }

