    await expectEnabled(this.payWithWalletButton(amount), `button ${UI_TEXT.payment.payWithWallet(amount)} is enabled`);
  }

  async shouldSeePayWithWalletDisabled(amount: string): Promise<void> {
    await expectDisabled(this.payWithWalletButton(amount), `button ${UI_TEXT.payment.payWithWallet(amount)} is disabled`);
  }

  async clickPayWithWallet(amount: string): Promise<void> {
    await this.payWithWalletButton(amount).click();
  }

  async shouldSeeCouponPanelButton(): Promise<void> {
    await this.couponPanel.shouldSeePanelButton();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.open();
  }

  async fillCouponCode(code: string): Promise<void> {
    await this.couponPanel.fillCouponCode(code);
  }

  async clickRedeemCoupon(): Promise<void> {
    await this.couponPanel.clickRedeem();
  }

  async shouldSeeDiscountApplied(percent: number): Promise<void> {
    await this.couponPanel.shouldSeeDiscountApplied(percent);
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await this.couponPanel.shouldSeeInvalidCouponError();
  }

  async shouldNotSeeDiscountApplied(): Promise<void> {
    await this.couponPanel.shouldNotSeeDiscountApplied();
  }

  async clickContinue(): Promise<void> {
    await this.page.getByRole('button').filter({ hasText: UI_TEXT.common.continueButton }).click();
  }
}

