import { UI_TEXT } from '@/utils/constants/ui-texts';

/** The page `Digital Wallet` with the wallet balance of the customer. */
export class DigitalWalletPage extends BasePage {
  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.wallet);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.wallet.heading);
  }

  async shouldSeeBalance(balance: string): Promise<void> {
    await expectVisible(this.page.getByText(balance, { exact: true }), `wallet balance ${balance}`);
  }
}

