import type { Locator } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { ShopProduct } from '@/utils/types/shop-types';

export interface OrderedProduct {
  product: ShopProduct;
  quantity: number;
}

/** The page `Order History`. Each order is a card with its ID, its products and its total. */
export class OrderHistoryPage extends BasePage {
  private get orderCards(): Locator {
    return this.page.locator('mat-card').filter({ has: this.page.getByText(UI_TEXT.basket.totalPrice('', 0).slice(0, 0) || 'Total Price', { exact: false }) });
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.orderHistory);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.orderHistory.heading);
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.noOrders, { exact: true }), 'message "You have not placed any orders yet."');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orderCards, count, `order count is ${count}`);
  }

  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
    const card = this.orderCards.filter({ hasText: orderId });
    await expectVisible(card, `order ${orderId}`);
    await expectVisible(card.getByText(total, { exact: false }), `total ${total} of order ${orderId}`);
  }

  async shouldSeeOrderProduct(orderId: string, { product, quantity }: OrderedProduct): Promise<void> {
    const card = this.orderCards.filter({ hasText: orderId });
    await expectVisible(card.getByText(product.name, { exact: true }), `${product.name} in order ${orderId}`);
    await expectVisible(card.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} in order ${orderId}`);
  }
}

