/** The host of the baseURL, used as the domain of the cookies that the app reads. */
export function hostOf(baseURL: string | undefined): string {
  if (!baseURL) {
    throw new Error('baseURL is not set. Set BASE_URL or keep the default in playwright.config.ts');
  }
  return new URL(baseURL).hostname;
}

