  shopCookies: [
    async ({ context, baseURL }, use) => {
      const domain = hostOf(baseURL);
      await context.addCookies(
        Object.values(APP_COOKIES).map((cookie) => ({ ...cookie, domain, path: '/' })),
      );
      await use();
    },
    { auto: true },
  ],
  api: async ({ request }, use) => {
    await use(new ShopApi(request));
  },
  navbar: async ({ page }, use) => {
    await use(new NavbarComponent(page));
  },
