/**
 * Test data of a customer, prepared through the API before the UI steps.
 * Each function acts on one customer. The spec passes its `api` fixture and its `customer`.
 */
import type { ShopApi } from '@/core/api/shop-api';
import { PURCHASE_LIMIT_PER_PRODUCT, SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import { buildCustomerCredentials } from '@/utils/helpers/customer-credentials';
import type { BasketLine, Customer, SavedCard } from '@/utils/types/shop-types';

/** Creates a new normal customer account and returns it with a token and a basket. */
export async function createCustomer(api: ShopApi): Promise<Customer> {
  const credentials = buildCustomerCredentials();
  const id = await api.users.register(credentials);
  const session = await api.users.login(credentials);
  return { ...credentials, id, token: session.token, basketId: session.basketId };
}

export async function addProductsToBasket(api: ShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
  for (const { product, quantity } of lines) {
    const productId = await api.products.findIdByName(product.name);
    await api.baskets.addProduct(customer, productId, quantity);
  }
}

/** Saves the saved address and the saved card of the test cases. Returns the card id, the payment id. */
export async function saveAddressAndCard(api: ShopApi, customer: Customer): Promise<number> {
  await api.payments.addAddress(customer, SAVED_ADDRESS);
  return api.payments.addCard(customer, SAVED_CARD);
}

/** The shop adds money to the wallet only with a saved card of the customer. */
export async function topUpWallet(api: ShopApi, customer: Customer, cardId: number, amount: number): Promise<void> {
  await api.payments.topUpWallet(customer, cardId, amount);
}

export { PURCHASE_LIMIT_PER_PRODUCT, type SavedCard };

