import { test } from '@/fixtures/pages.fixture';
import { createCustomer } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { buildWrongPassword } from '@/utils/helpers/customer-credentials';

test.describe('Login with a customer account', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
  annotation: { type: 'test-case', description: 'TC-01' },
}, () => {
  test('Login with a valid and an invalid password', async ({ api, loginPage, navbar, productListPage }) => {
    const customer = await test.step('Precondition: create a new customer account', () => createCustomer(api));
    const wrongPassword = buildWrongPassword(customer.password);

    await test.step('1. Open the login page', async () => {
      await loginPage.open();
      await loginPage.shouldSeePage();
    });

    await test.step('2. Log in with the wrong password', async () => {
      await loginPage.fillEmail(customer.email);
      await loginPage.fillPassword(wrongPassword);
      await loginPage.clickLogin();
      await loginPage.shouldSeeInvalidCredentialsError();
      await loginPage.shouldStayOnLoginPage();
    });

    await test.step('3. Open the account menu before the login', async () => {
      await navbar.openAccountMenu();
      await navbar.shouldNotSeeAccountEmail(customer.email);
    });

    await test.step('4. Log in with the correct password', async () => {
      await navbar.closeAccountMenu();
      await loginPage.fillEmail(customer.email);
      await loginPage.fillPassword(customer.password);
      await loginPage.clickLogin();
      await productListPage.shouldSeePage();
    });

    await test.step('5. Open the account menu after the login', async () => {
      await navbar.openAccountMenu();
      await navbar.shouldSeeAccountEmail(customer.email);
      await navbar.shouldSeeLogoutItem();
    });
  });
});

