import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-data';

const RASPBERRY_JUICE = PRODUCTS.raspberryJuice;
const EGGFRUIT_JUICE = PRODUCTS.eggfruitJuice;

const TOTAL_OF_BOTH_PRODUCTS = '13.98¤';
const TOTAL_AFTER_INCREASE = '18.97¤';
const TOTAL_OF_EGGFRUIT_ONLY = '8.99¤';

test.describe('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, () => {
  test('Change the quantity and remove a product in the basket', async ({ api, customer, basketPage, navbar }) => {
    await test.step('Precondition: the basket holds one Raspberry Juice and one Eggfruit Juice', async () => {
      await addProductsToBasket(api, customer, [
        { product: RASPBERRY_JUICE, quantity: 1 },
        { product: EGGFRUIT_JUICE, quantity: 1 },
      ]);
    });

    await test.step('1. Open the basket', async () => {
      await basketPage.open();
      await basketPage.shouldSeeProductRow({ product: RASPBERRY_JUICE, quantity: 1 });
      await basketPage.shouldSeeProductRow({ product: EGGFRUIT_JUICE, quantity: 1 });
      await basketPage.shouldSeeTotalPrice(TOTAL_OF_BOTH_PRODUCTS);
      await navbar.shouldSeeBasketCounter(2);
    });

    await test.step('2. Click the plus button in the row of Raspberry Juice', async () => {
      await basketPage.clickIncreaseQuantity(RASPBERRY_JUICE);
      await basketPage.shouldSeeProductRow({ product: RASPBERRY_JUICE, quantity: 2 });
      await basketPage.shouldSeeTotalPrice(TOTAL_AFTER_INCREASE);
      await navbar.shouldSeeBasketCounter(3);
    });

    await test.step('3. Click the minus button in the row of Raspberry Juice', async () => {
      await basketPage.clickDecreaseQuantity(RASPBERRY_JUICE);
      await basketPage.shouldSeeProductRow({ product: RASPBERRY_JUICE, quantity: 1 });
      await basketPage.shouldSeeTotalPrice(TOTAL_OF_BOTH_PRODUCTS);
      await navbar.shouldSeeBasketCounter(2);
    });

    await test.step('4. Click the minus button in the row of Raspberry Juice again', async () => {
      await basketPage.clickDecreaseQuantity(RASPBERRY_JUICE);
      await basketPage.shouldSeeProductRow({ product: RASPBERRY_JUICE, quantity: 1 });
      await basketPage.shouldSeeTotalPrice(TOTAL_OF_BOTH_PRODUCTS);
    });

    await test.step('5. Click the trash button in the row of Raspberry Juice', async () => {
      await basketPage.clickRemoveProduct(RASPBERRY_JUICE);
      await basketPage.shouldNotSeeProductRow(RASPBERRY_JUICE);
      await basketPage.shouldSeeProductRow({ product: EGGFRUIT_JUICE, quantity: 1 });
      await basketPage.shouldSeeTotalPrice(TOTAL_OF_EGGFRUIT_ONLY);
      await navbar.shouldSeeBasketCounter(1);
    });
  });
});

