import type { Page } from '@playwright/test';
import { expectCount, expectHidden, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_TEXT } from '@/utils/constants/ui-texts';

/** The top bar: the account menu and the basket counter. Present on every page of the shop. */
export class NavbarComponent {
  constructor(private readonly page: Page) {}

  private get basketButton() {
    return this.page.getByRole('button', { name: UI_TEXT.navbar.basketButton });
  }

  private get accountMenu() {
    return this.page.getByRole('menu').first();
  }

  async openBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await expectVisible(this.basketButton.getByText(String(count), { exact: true }), `basket counter ${count}`);
  }

  async openAccountMenu(): Promise<void> {
    await this.page.getByRole('button', { name: UI_TEXT.navbar.accountMenuButton }).click();
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectHidden(this.accountMenu, 'account menu is closed');
  }

  async shouldSeeLoginItem(): Promise<void> {
    await expectVisible(this.accountMenu.getByRole('menuitem', { name: UI_TEXT.navbar.loginItem }), 'account menu item "Login"');
  }

  async shouldNotSeeAccountEmail(email: string): Promise<void> {
    await this.shouldSeeLoginItem();
    await expectCount(this.accountMenu.getByText(email), 0, 'account menu does not show the email');
  }

  async shouldSeeAccountEmail(email: string): Promise<void> {
    await expectVisible(this.accountMenu.getByRole('menuitem').filter({ hasText: email }), `account menu shows ${email}`);
  }

  async shouldSeeLogoutItem(): Promise<void> {
    await expectVisible(this.accountMenu.getByRole('menuitem', { name: UI_TEXT.navbar.logoutItem }), 'account menu item "Logout"');
  }

  async openOrdersAndPayment(): Promise<void> {
    await this.page.getByRole('menuitem', { name: UI_TEXT.navbar.ordersAndPaymentItem }).click();
  }

  async clickOrderHistory(): Promise<void> {
    await this.page.getByRole('menuitem', { name: UI_TEXT.navbar.orderHistoryItem }).click();
  }

  async clickDigitalWallet(): Promise<void> {
    await this.page.getByRole('menuitem', { name: UI_TEXT.navbar.walletItem }).click();
  }
}

