import { addProductsToBasket, saveAddressAndCard } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  ORDER_TOTALS,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD,
} from '@/utils/constants/shop-data';
import { currentMonthCoupon } from '@/utils/helpers/coupon-helper';

test.describe('Valid coupon on the payment step', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.coupon],
  annotation: { type: 'test-case', description: 'TC-05' },
}, () => {
  test('Valid coupon of the current month gives the discount on the products', async ({
    api,
    customer,
    basketPage,
    navbar,
    addressSelectionPage,
    deliveryMethodPage,
    paymentPage,
    orderSummaryPage,
  }) => {
    const couponCode = currentMonthCoupon(COUPON_DISCOUNT_PERCENT);

    await test.step('Precondition: the customer has a saved address and card, and two Eggfruit Juice in the basket', async () => {
      await saveAddressAndCard(api, customer);
      await addProductsToBasket(api, customer, [{ product: PRODUCTS.eggfruitJuice, quantity: 2 }]);
      await navbar.shouldSeeLoggedInAs(customer.email);
    });

    await test.step('1. Open the basket and click Checkout', async () => {
      await basketPage.open();
      await basketPage.clickCheckout();
      await addressSelectionPage.shouldSeePage();
      await addressSelectionPage.shouldSeeSavedAddress(SAVED_ADDRESS);
    });

    await test.step('2. Select the saved address and continue', async () => {
      await addressSelectionPage.selectSavedAddress(SAVED_ADDRESS);
      await addressSelectionPage.clickContinue();
      await deliveryMethodPage.shouldSeePage();
      await deliveryMethodPage.shouldSeeDeliveryOption(DELIVERY_METHODS.oneDay);
      await deliveryMethodPage.shouldSeeDeliveryOption(DELIVERY_METHODS.fast);
      await deliveryMethodPage.shouldSeeDeliveryOption(DELIVERY_METHODS.standard);
    });

    await test.step('3. Select One Day Delivery and continue', async () => {
      await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.oneDay);
      await deliveryMethodPage.clickContinue();
      await paymentPage.shouldSeePage();
      await paymentPage.shouldSeeSavedCard(SAVED_CARD);
      await paymentPage.shouldSeeCouponPanelButton();
    });

    await test.step('4. Redeem the coupon of the current month', async () => {
      await paymentPage.openCouponPanel();
      await paymentPage.fillCouponCode(couponCode);
      await paymentPage.clickRedeemCoupon();
      await paymentPage.shouldSeeDiscountApplied(COUPON_DISCOUNT_PERCENT);
    });

    await test.step('5. Select the saved card and continue', async () => {
      await paymentPage.selectSavedCard(SAVED_CARD);
      await paymentPage.clickContinue();
      await orderSummaryPage.shouldSeePage();
      await orderSummaryPage.shouldSeeTotals(ORDER_TOTALS.twoEggfruitWithDiscount);
    });
  });
});

