import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket, saveAddressAndCard, topUpWallet } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, ORDER_TOTALS, PRODUCTS, SAVED_ADDRESS, SAVED_CARD, WALLET_TOP_UPS } from '@/utils/constants/shop-data';
