import type { Locator } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectDisabled, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { BasketLine, ShopProduct } from '@/utils/types/shop-types';

/** The basket `/#/basket`. Each product is a row with the name, the quantity, the price and three icon buttons. */
export class BasketPage extends BasePage {
  private get checkoutButton() {
    return this.page.getByRole('button', { name: UI_TEXT.basket.checkoutButton });
  }

  private get dataRows() {
    return this.page.getByRole('row').filter({ has: this.page.getByRole('cell') });
  }

  private rowOf(product: ShopProduct): Locator {
    return this.page.getByRole('row').filter({ has: this.page.getByText(product.name, { exact: true }) });
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.basket.heading);
  }

  async shouldSeeProductRow({ product, quantity }: BasketLine): Promise<void> {
    const row = this.rowOf(product);
    await expectVisible(row, `basket row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: product.price, exact: true }), `price ${product.price} of ${product.name}`);
  }

  async shouldNotSeeProductRow(product: ShopProduct): Promise<void> {
    await expectCount(this.rowOf(product), 0, `no basket row of ${product.name}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.dataRows, 0, 'the basket has no product rows');
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.basket.totalPrice(total), { exact: true }), `total ${total}`);
  }

  async clickIncreaseQuantity(product: ShopProduct, times = 1): Promise<void> {
    await this.clickRowIcon(product, UI_TEXT.basket.increaseIcon, times);
  }

  async clickDecreaseQuantity(product: ShopProduct): Promise<void> {
    await this.clickRowIcon(product, UI_TEXT.basket.decreaseIcon, 1);
  }

  async clickRemoveProduct(product: ShopProduct): Promise<void> {
    await this.clickRowIcon(product, UI_TEXT.basket.removeIcon, 1);
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'button Checkout is disabled');
  }

  private async clickRowIcon(product: ShopProduct, icon: string, times: number): Promise<void> {
    const button = this.rowOf(product).getByRole('button').filter({ hasText: icon });
    for (let click = 0; click < times; click += 1) {
      await button.click();
    }
  }
}

/**
 * Texts of the shop UI in English. Product data such as `Your Basket` stays as the shop shows it.
 * Icons of the shop are ligature text in the DOM, so the icon names are kept here too.
 */
