import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-data';
import { UI_TEXT } from '@/utils/constants/ui-texts';

const EGGFRUIT_JUICE = PRODUCTS.eggfruitJuice;

test.describe('Add a product to the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-02' },
}, () => {
  test('Add a product to the basket from the product list', async ({ customer, productListPage, navbar, basketPage }) => {
    await test.step('Precondition: the customer is logged in and the basket is empty', async () => {
      await navbar.shouldSeeLoggedInAs(customer.email);
      await navbar.shouldSeeBasketCounter(0);
    });

    await test.step('1. Open the product list', async () => {
      await productListPage.open();
      await productListPage.shouldSeeProduct(EGGFRUIT_JUICE);
      await navbar.shouldSeeBasketCounter(0);
    });

    await test.step('2. Click Add to Basket on the product', async () => {
      await productListPage.clickAddToBasket(EGGFRUIT_JUICE);
      await productListPage.shouldSeeMessage(UI_TEXT.messages.placedIntoBasket(EGGFRUIT_JUICE.name));
      await navbar.shouldSeeBasketCounter(1);
    });

    await test.step('3. Open the basket', async () => {
      await navbar.openBasket();
      await basketPage.shouldSeePage();
      await basketPage.shouldSeeProductRow({ product: EGGFRUIT_JUICE, quantity: 1 });
    });

    await test.step('4. Read the total price of the basket', async () => {
      await basketPage.shouldSeeTotalPrice(EGGFRUIT_JUICE.price);
    });
  });
});

