import { test } from '@/fixtures/customer.fixture';
import { addProductsToBasket, saveAddressAndCard, topUpWallet } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, ORDER_TOTALS, PRODUCTS, SAVED_ADDRESS, WALLET_TOP_UPS } from '@/utils/constants/shop-data';
import { DateHelper } from '@/utils/helpers/date-helper';

const EGGFRUIT_JUICE = PRODUCTS.eggfruitJuice;
const ORDER_TOTAL = ORDER_TOTALS.eggfruitWithStandardDelivery.total;
const BALANCE_AFTER_FIRST_TOP_UP = '5.00';
const BALANCE_AFTER_SECOND_TOP_UP = '8.99';
const BALANCE_AFTER_PAYMENT_AND_BONUS = '1.00';
const BONUS_POINTS_OF_ORDER = '1';

test.describe('Payment with the wallet', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, () => {
  // The test pays twice, with two wallet balances. The checkout flow is long.
  test.setTimeout(DateHelper.minutesToMs(2));

  test('Pay with the wallet only when the balance covers the order total', async ({
    api,
    customer,
    navbar,
    basketPage,
    addressSelectionPage,
    deliveryMethodPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
    digitalWalletPage,
  }) => {
    const savedCardId = await test.step('Precondition: the customer has a saved address and card, a wallet balance of 5.00, and one Eggfruit Juice in the basket', async () => {
      const cardId = await saveAddressAndCard(api, customer);
      await topUpWallet(api, customer, cardId, WALLET_TOP_UPS.initialBalance);
      await addProductsToBasket(api, customer, [{ product: EGGFRUIT_JUICE, quantity: 1 }]);
      await navbar.shouldSeeLoggedInAs(customer.email);
      return cardId;
    });

    await test.step('1. Open the basket, click Checkout, select the saved address and continue', async () => {
      await basketPage.open();
      await basketPage.clickCheckout();
      await addressSelectionPage.shouldSeePage();
      await addressSelectionPage.selectSavedAddress(SAVED_ADDRESS);
      await addressSelectionPage.clickContinue();
      await deliveryMethodPage.shouldSeePage();
    });

    await test.step('2. Select Standard Delivery and continue', async () => {
      await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.standard);
      await deliveryMethodPage.clickContinue();
      await paymentPage.shouldSeePage();
      await paymentPage.shouldSeeWalletBalance(BALANCE_AFTER_FIRST_TOP_UP);
      await paymentPage.shouldSeePayWithWalletEnabled(ORDER_TOTAL);
    });

    await test.step('3. Read the wallet button', async () => {
      await paymentPage.shouldSeePayWithWalletDisabled(ORDER_TOTAL);
    });

    await test.step('4. Open the order history', async () => {
      await navbar.openAccountMenu();
      await navbar.openOrdersAndPayment();
      await navbar.clickOrderHistory();
      await orderHistoryPage.shouldSeeNoOrders();
    });

    await test.step('5. Open the digital wallet', async () => {
      await navbar.openAccountMenu();
      await navbar.openOrdersAndPayment();
      await navbar.clickDigitalWallet();
      await digitalWalletPage.shouldSeeBalance(BALANCE_AFTER_FIRST_TOP_UP);
    });

    await test.step('Precondition: add 3.99 to the wallet with the saved card, so that the balance equals the order total', async () => {
      await topUpWallet(api, customer, savedCardId, WALLET_TOP_UPS.balanceForOrderTotal);
    });

    await test.step('6. Open the basket, click Checkout, select the saved address, continue and select Standard Delivery', async () => {
      await basketPage.open();
      await basketPage.clickCheckout();
      await addressSelectionPage.selectSavedAddress(SAVED_ADDRESS);
      await addressSelectionPage.clickContinue();
      await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.standard);
      await deliveryMethodPage.clickContinue();
      await paymentPage.shouldSeePage();
      await paymentPage.shouldSeeWalletBalance(BALANCE_AFTER_SECOND_TOP_UP);
      await paymentPage.shouldSeePayWithWalletEnabled(ORDER_TOTAL);
    });

    await test.step('7. Click the wallet payment button', async () => {
      await paymentPage.clickPayWithWallet(ORDER_TOTAL);
      await orderSummaryPage.shouldSeePage();
      await orderSummaryPage.shouldSeeWalletPaymentMethod();
      await orderSummaryPage.shouldSeeTotalPrice(ORDER_TOTAL);
    });

    await test.step('8. Place the order', async () => {
      await orderSummaryPage.clickPlaceOrder();
      await orderCompletionPage.shouldSeePage();
    });

    await test.step('9. Open the digital wallet', async () => {
      await navbar.openAccountMenu();
      await navbar.openOrdersAndPayment();
      await navbar.clickDigitalWallet();
      await digitalWalletPage.shouldSeeBalance(BALANCE_AFTER_PAYMENT_AND_BONUS);
    });

    await test.step('10. Open the order history', async () => {
      await navbar.openAccountMenu();
      await navbar.openOrdersAndPayment();
      await navbar.clickOrderHistory();
      await orderHistoryPage.shouldSeeOrderCount(1);
      await orderHistoryPage.shouldSeeSingleOrder(ORDER_TOTAL, BONUS_POINTS_OF_ORDER);
    });
  });
});

