  private get checkoutButton() {
    return this.page.getByRole('button', { name: UI_TEXT.basket.checkoutButton });
  }

  private get dataRows() {
    return this.page.getByRole('row').filter({ has: this.page.getByRole('cell') });
  }

  private rowOf(product: ShopProduct): Locator {
    return this.page.getByRole('row').filter({ has: this.page.getByText(product.name, { exact: true }) });
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.basket);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.basket.heading);
  }

