    const row = this.rowOf(product);
    await expectVisible(row, `basket row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: product.price, exact: true }), `price ${product.price} of ${product.name}`);
  }

  async shouldNotSeeProductRow(product: ShopProduct): Promise<void> {
    await expectCount(this.rowOf(product), 0, `no basket row of ${product.name}`);
  }

  async shouldSeeNoProducts(): Promise<void> {
    await expectCount(this.dataRows, 0, 'the basket has no product rows');
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.basket.totalPrice(total), { exact: true }), `total ${total}`);
  }

  async clickIncreaseQuantity(product: ShopProduct, times = 1): Promise<void> {
    await this.clickRowIcon(product, UI_TEXT.basket.increaseIcon, times);
