  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-04' },
}, () => {
  test('Purchase limit for one product in the basket', async ({ customer, productListPage, basketPage, navbar }) => {
    await test.step('Precondition: the customer is logged in and the basket is empty', async () => {
      await productListPage.open();
      await navbar.shouldSeeLoggedInAs(customer.email);
      await navbar.shouldSeeBasketCounter(0);
    });

    await test.step('1. Open the product list and click Add to Basket on Apple Juice', async () => {
      await productListPage.open();
      await productListPage.clickAddToBasket(APPLE_JUICE);
      await productListPage.shouldSeeMessage(UI_TEXT.messages.placedIntoBasket(APPLE_JUICE.name));
      await navbar.shouldSeeBasketCounter(1);
    });

    await test.step('2. Open the basket and increase the quantity to the limit', async () => {
      await navbar.openBasket();
      await basketPage.shouldSeePage();
      await basketPage.clickIncreaseQuantity(APPLE_JUICE, PURCHASE_LIMIT_PER_PRODUCT - 1);
      await basketPage.shouldSeeProductRow({ product: APPLE_JUICE, quantity: PURCHASE_LIMIT_PER_PRODUCT });
      await basketPage.shouldSeeTotalPrice(TOTAL_AT_LIMIT);
      await basketPage.shouldNotSeeMessageContaining(LIMIT_MESSAGE);
    });

    await test.step('3. Click the plus button one more time', async () => {
      await basketPage.clickIncreaseQuantity(APPLE_JUICE);
      await basketPage.shouldSeeMessage(LIMIT_MESSAGE);
    });

    await test.step('4. Read the basket', async () => {
      await basketPage.shouldSeeProductRow({ product: APPLE_JUICE, quantity: PURCHASE_LIMIT_PER_PRODUCT });
      await basketPage.shouldSeeTotalPrice(TOTAL_AT_LIMIT);
      await navbar.shouldSeeBasketCounter(PURCHASE_LIMIT_PER_PRODUCT);
    });

    await test.step('5. Click Add to Basket on Apple Juice in the product list', async () => {
      await productListPage.open();
      await productListPage.clickAddToBasket(APPLE_JUICE);
      await productListPage.shouldSeeMessage(LIMIT_MESSAGE);
      await navbar.shouldSeeBasketCounter(PURCHASE_LIMIT_PER_PRODUCT);
    });
  });
});

