import type { Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { OrderTotalsTableComponent } from '@/page-objects/components/order-totals-table.component';
import { expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import { lastFourDigits } from '@/utils/helpers/card-helper';
import type { OrderTotals, SavedAddress, SavedCard, ShopProduct } from '@/utils/types/shop-types';

/** The step `Order Summary` before the order is placed. */
export class OrderSummaryPage extends BasePage {
  private readonly totalsTable: OrderTotalsTableComponent;

  constructor(page: Page) {
    super(page);
    this.totalsTable = new OrderTotalsTableComponent(page);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.orderSummary.heading);
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    await expectVisible(this.page.getByText(address.streetAddress), `delivery address ${address.streetAddress}`);
  }

  async shouldSeeCardPaymentMethod(card: SavedCard): Promise<void> {
    const digits = lastFourDigits(card.cardNumber);
    await expectVisible(this.page.getByText(`Card ending in ${digits}`), `payment method card ending in ${digits}`);
  }

  async shouldSeeWalletPaymentMethod(): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.orderSummary.digitalWallet), 'payment method Digital Wallet');
  }

  async shouldSeeProductRow(product: ShopProduct, quantity: number): Promise<void> {
    await this.totalsTable.shouldSeeProductRow(product, quantity);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await this.totalsTable.shouldSeeTotals(totals);
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await this.totalsTable.shouldSeeTotalPrice(total);
  }

  async clickPlaceOrder(): Promise<void> {
    await this.page.getByRole('button').filter({ hasText: UI_TEXT.orderSummary.placeOrderButton }).click();
  }
}

