import { test } from '@/fixtures/customer.fixture';
import { saveAddressAndCard } from '@/tests/helpers/customer-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  ORDER_TOTALS,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD,
} from '@/utils/constants/shop-data';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import { currentMonthCoupon } from '@/utils/helpers/coupon-helper';

const EGGFRUIT_JUICE = PRODUCTS.eggfruitJuice;
const CARROT_JUICE = PRODUCTS.carrotJuice;

test.describe('Order with a card, from basket to order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, () => {
  test('Order two Eggfruit Juice and one Carrot Juice with a card and a coupon', async ({
    api,
    customer,
    navbar,
    productListPage,
    basketPage,
    addressSelectionPage,
    deliveryMethodPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
  }) => {
    const couponCode = currentMonthCoupon(COUPON_DISCOUNT_PERCENT);

    await test.step('Precondition: the customer has a saved address and card', async () => {
      await saveAddressAndCard(api, customer);
    });

    await test.step('1. Open the product list and click Add to Basket on Eggfruit Juice two times and on Carrot Juice one time', async () => {
      await productListPage.open();
      await productListPage.clickAddToBasket(EGGFRUIT_JUICE);
      await productListPage.clickAddToBasket(EGGFRUIT_JUICE);
      await productListPage.clickAddToBasket(CARROT_JUICE);
      await navbar.shouldSeeBasketCounter(3);
    });

    await test.step('2. Open the basket', async () => {
      await basketPage.open();
      await basketPage.shouldSeeProductRow({ product: EGGFRUIT_JUICE, quantity: 2 });
      await basketPage.shouldSeeProductRow({ product: CARROT_JUICE, quantity: 1 });
      await basketPage.shouldSeeTotalPrice(ORDER_TOTALS.eggfruitAndCarrotWithDiscount.items);
    });

    await test.step('3. Click Checkout, select the saved address and continue', async () => {
      await basketPage.clickCheckout();
      await addressSelectionPage.shouldSeePage();
      await addressSelectionPage.selectSavedAddress(SAVED_ADDRESS);
      await addressSelectionPage.clickContinue();
      await deliveryMethodPage.shouldSeePage();
    });

    await test.step('4. Select One Day Delivery and continue', async () => {
      await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.oneDay);
      await deliveryMethodPage.clickContinue();
      await paymentPage.shouldSeePage();
    });

    await test.step('5. Redeem the coupon of the current month', async () => {
      await paymentPage.openCouponPanel();
      await paymentPage.fillCouponCode(couponCode);
      await paymentPage.clickRedeemCoupon();
      await paymentPage.shouldSeeDiscountApplied(COUPON_DISCOUNT_PERCENT);
    });

    await test.step('6. Select the saved card and continue', async () => {
      await paymentPage.selectSavedCard(SAVED_CARD);
      await paymentPage.clickContinue();
      await orderSummaryPage.shouldSeePage();
      await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
      await orderSummaryPage.shouldSeeCardPaymentMethod(SAVED_CARD);
      await orderSummaryPage.shouldSeeTotals(ORDER_TOTALS.eggfruitAndCarrotWithDiscount);
    });

    const orderId = await test.step(`7. Click ${UI_TEXT.orderSummary.placeOrderButton}`, async () => {
      await orderSummaryPage.clickPlaceOrder();
      await orderCompletionPage.shouldSeePage();
      return orderCompletionPage.readOrderId();
    });

    await test.step('8. Read the order summary on the confirmation page', async () => {
      await orderCompletionPage.shouldSeeProductRow(EGGFRUIT_JUICE, 2);
      await orderCompletionPage.shouldSeeProductRow(CARROT_JUICE, 1);
      await orderCompletionPage.shouldSeeTotals(ORDER_TOTALS.eggfruitAndCarrotWithDiscount);
    });

    await test.step('9. Read the basket counter and open the empty basket', async () => {
      await navbar.shouldSeeBasketCounter(0);
      await basketPage.open();
      await basketPage.shouldSeeNoProducts();
      await basketPage.shouldSeeCheckoutDisabled();
    });

    await test.step('10. Open the order history', async () => {
      await navbar.openAccountMenu();
      await navbar.openOrdersAndPayment();
      await navbar.clickOrderHistory();
      await orderHistoryPage.shouldSeePage();
      await orderHistoryPage.shouldSeeOrderCount(1);
      await orderHistoryPage.shouldSeeOrder(orderId, ORDER_TOTALS.eggfruitAndCarrotWithDiscount.total);
      await orderHistoryPage.shouldSeeOrderProduct(orderId, { product: EGGFRUIT_JUICE, quantity: 2 });
      await orderHistoryPage.shouldSeeOrderProduct(orderId, { product: CARROT_JUICE, quantity: 1 });
    });
  });
});

import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { ShopProduct } from '@/utils/types/shop-types';

export interface OrderedProduct {
  product: ShopProduct;
  quantity: number;
}

const ORDER_ID_LABEL = 'Order ID #';

/**
 * The page `/#/order-history`. Each order shows `Order ID #<id>`, `Total Price <total>`, `Bonus <points>`
 * and a table of its products.
 */
export class OrderHistoryPage extends BasePage {
  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.orderHistory);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlHash(this.page, UI_ROUTES.orderHistory, 'order history page is open');
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.noOrders, { exact: true }), 'message "You have not placed any orders yet."');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.page.getByText(ORDER_ID_LABEL), count, `order count is ${count}`);
  }

  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
    await expectVisible(this.page.getByText(`${ORDER_ID_LABEL}${orderId}`), `order ${orderId}`);
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.totalPrice(total)), `total ${total} of order ${orderId}`);
  }

  /** The only order of the customer: its total and its bonus points. */
  async shouldSeeSingleOrder(total: string, bonusPoints: string): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.totalPrice(total)), `total ${total} of the order`);
    await expectVisible(this.page.getByText(new RegExp(`${UI_TEXT.orderHistory.bonus} ${bonusPoints}\\b`)), `bonus points ${bonusPoints} of the order`);
  }

  async shouldSeeOrderProduct({ product, quantity }: OrderedProduct): Promise<void> {
    const row = this.page.getByRole('row').filter({ has: this.page.getByRole('cell', { name: product.name, exact: true }) });
    await expectVisible(row, `order row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
  }
}

