import type { Page } from '@playwright/test';
import { expectCount, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { OrderTotals, ShopProduct } from '@/utils/types/shop-types';

/** The product rows and the totals table `Order Summary`. The payment summary and the order confirmation both show it. */
export class OrderTotalsTableComponent {
  constructor(private readonly page: Page) {}

  private rowWithCell(cellName: string) {
    return this.page.getByRole('row').filter({ has: this.page.getByRole('cell', { name: cellName, exact: true }) });
  }

  private productRow(product: ShopProduct) {
    return this.page.getByRole('row').filter({ has: this.page.getByText(product.name, { exact: true }) });
  }

  async shouldSeeProductRow(product: ShopProduct, quantity: number): Promise<void> {
    const row = this.productRow(product);
    await expectVisible(row, `order row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await this.shouldSeeTotalLine(UI_TEXT.orderSummary.items, totals.items);
    await this.shouldSeeTotalLine(UI_TEXT.orderSummary.delivery, totals.delivery);
    await this.shouldSeeTotalLine(UI_TEXT.orderSummary.promotion, totals.promotion);
    await this.shouldSeeTotalLine(UI_TEXT.orderSummary.total, totals.total);
  }

  async shouldSeeTotalPrice(total: string): Promise<void> {
    await this.shouldSeeTotalLine(UI_TEXT.orderSummary.total, total);
  }

  private async shouldSeeTotalLine(label: string, value: string): Promise<void> {
    const row = this.rowWithCell(label);
    await expectVisible(row.getByRole('cell', { name: value, exact: true }), `${label} is ${value}`);
  }

  async shouldNotSeeProductRow(product: ShopProduct): Promise<void> {
    await expectCount(this.productRow(product), 0, `no order row of ${product.name}`);
  }
}

