import type { Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectDisabled, expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
import { APP_SESSION_KEYS } from '@/utils/constants/app-cookies';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { Customer } from '@/utils/types/shop-types';

export class LoginPage extends BasePage {
  constructor(
    page: Page,
    private readonly appHost: string,
  ) {
    super(page);
  }

  private get emailField() {
    return this.page.getByRole('textbox', { name: UI_TEXT.login.emailField });
  }

  private get passwordField() {
    return this.page.getByRole('textbox', { name: UI_TEXT.login.passwordField });
  }

  private get loginButton() {
    return this.page.getByRole('button', { name: UI_TEXT.login.loginButton, exact: true });
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.login);
  }

  async shouldSeePage(): Promise<void> {
    await this.shouldSeeTitle(UI_TEXT.login.heading);
    await expectVisible(this.emailField, 'field Email');
    await expectVisible(this.passwordField, 'field Password');
    await expectVisible(this.loginButton, 'button Log in');
  }

  async fillEmail(email: string): Promise<void> {
    await this.emailField.fill(email);
  }

  async fillPassword(password: string): Promise<void> {
    await this.passwordField.fill(password);
  }

  async clickLogin(): Promise<void> {
    await this.loginButton.click();
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await this.shouldSeeMessage(UI_TEXT.login.invalidCredentials);
  }

  async shouldStayOnLoginPage(): Promise<void> {
    await expectUrlHash(this.page, UI_ROUTES.login, 'login page stays open');
  }

  async shouldSeeLoginButtonDisabled(): Promise<void> {
    await expectDisabled(this.loginButton, 'button Log in is disabled');
  }

  /**
   * Puts a logged-in session of the customer into the browser, without the login form.
   * The app reads the token from localStorage, the cookie and the basket id from sessionStorage.
   */
  async authenticate(customer: Customer): Promise<void> {
    await this.page.context().addCookies([
      { name: APP_SESSION_KEYS.token, value: customer.token, domain: this.appHost, path: '/' },
    ]);
    await this.page.addInitScript(
      ({ tokenKey, basketKey, token, basketId }) => {
        localStorage.setItem(tokenKey, token);
        sessionStorage.setItem(basketKey, String(basketId));
      },
      {
        tokenKey: APP_SESSION_KEYS.token,
        basketKey: APP_SESSION_KEYS.basketId,
        token: customer.token,
        basketId: customer.basketId,
      },
    );
  }
}

