import type { Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { OrderTotalsTableComponent } from '@/page-objects/components/order-totals-table.component';
import { expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { OrderTotals, ShopProduct } from '@/utils/types/shop-types';

const ORDER_ID_IN_URL = /\/order-completion\/([^/?#]+)/;

/** The confirmation page `/#/order-completion/<order ID>` after the order is placed. */
export class OrderCompletionPage extends BasePage {
  private readonly totalsTable: OrderTotalsTableComponent;

  constructor(page: Page) {
    super(page);
    this.totalsTable = new OrderTotalsTableComponent(page);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlHash(this.page, UI_ROUTES.orderCompletion(''), 'order completion page is open');
    await expectVisible(this.page.getByText(UI_TEXT.orderCompletion.thankYou, { exact: true }), 'message "Thank you for your purchase!"');
  }

  /** The order ID is the last part of the confirmation URL. */
  async readOrderId(): Promise<string> {
    const match = ORDER_ID_IN_URL.exec(this.page.url());
    if (!match) {
      throw new Error(`Order ID is not in the URL: ${this.page.url()}`);
    }
    return match[1];
  }

  async shouldSeeProductRow(product: ShopProduct, quantity: number): Promise<void> {
    await this.totalsTable.shouldSeeProductRow(product, quantity);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await this.totalsTable.shouldSeeTotals(totals);
  }
}

