1	import type { Locator, Page } from '@playwright/test';
2	import { BasePage } from '@/page-objects/base-page';
3	import { expectDisabled, expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
4	import { APP_SESSION_KEYS } from '@/utils/constants/app-cookies';
5	import { UI_ROUTES } from '@/utils/constants/routes';
6	import { UI_TEXT } from '@/utils/constants/ui-texts';
7	import type { Customer } from '@/utils/types/shop-types';
8	
9	export class LoginPage extends BasePage {
10	  constructor(
11	    page: Page,
12	    private readonly appHost: string,
13	  ) {
14	    super(page);
15	  }
16	
17	  private get emailField(): Locator {
18	    return this.page.getByRole('textbox', { name: UI_TEXT.login.emailField });
19	  }
20	
21	  private get passwordField(): Locator {
22	    return this.page.getByRole('textbox', { name: UI_TEXT.login.passwordField });
23	  }
24	
25	  private get loginButton(): Locator {
26	    return this.page.getByRole('button', { name: UI_TEXT.login.loginButton, exact: true });
27	  }
28	
29	  async open(): Promise<void> {
30	    await this.openRoute(UI_ROUTES.login);
31	  }
32	
33	  async shouldSeePage(): Promise<void> {
34	    await this.shouldSeeTitle(UI_TEXT.login.heading);
35	    await expectVisible(this.emailField, 'field Email');
36	    await expectVisible(this.passwordField, 'field Password');
37	    await expectVisible(this.loginButton, 'button Log in');
38	  }
39	
40	  async fillEmail(email: string): Promise<void> {
41	    await this.emailField.fill(email);
42	  }
43	
44	  async fillPassword(password: string): Promise<void> {
45	    await this.passwordField.fill(password);
46	  }
47	
48	  async clickLogin(): Promise<void> {
49	    await this.loginButton.click();
50	  }
51	
52	  async shouldSeeInvalidCredentialsError(): Promise<void> {
53	    await this.shouldSeeMessage(UI_TEXT.login.invalidCredentials);
54	  }
55	
56	  async shouldStayOnLoginPage(): Promise<void> {
57	    await expectUrlHash(this.page, UI_ROUTES.login, 'login page stays open');
58	  }
59	
60	  async shouldSeeLoginButtonDisabled(): Promise<void> {
61	    await expectDisabled(this.loginButton, 'button Log in is disabled');
62	  }
63	
64	  /**
65	   * Puts a logged-in session of the customer into the browser, without the login form.
66	   * The app reads the token from localStorage, the cookie and the basket id from sessionStorage.
67	   */
68	  async authenticate(customer: Customer): Promise<void> {
69	    await this.page.context().addCookies([
70	      { name: APP_SESSION_KEYS.token, value: customer.token, domain: this.appHost, path: '/' },
71	    ]);
72	    await this.page.addInitScript(
73	      ({ tokenKey, basketKey, token, basketId }) => {
74	        localStorage.setItem(tokenKey, token);
75	        sessionStorage.setItem(basketKey, String(basketId));
76	      },
77	      {
78	        tokenKey: APP_SESSION_KEYS.token,
79	        basketKey: APP_SESSION_KEYS.basketId,
80	        token: customer.token,
81	        basketId: customer.basketId,
82	      },
83	    );
84	  }
85	}
