8	/** The basket `/#/basket`. Each product is a row with the name, the quantity, the price and three icon buttons. */
9	export class BasketPage extends BasePage {
10	  private get checkoutButton(): Locator {
11	    return this.page.getByRole('button', { name: UI_TEXT.basket.checkoutButton });
12	  }
13	
14	  private get dataRows(): Locator {
15	    return this.page.getByRole('row').filter({ has: this.page.getByRole('cell') });
16	  }
17	
18	  private rowOf(product: ShopProduct): Locator {
19	    return this.page.getByRole('row').filter({ has: this.page.getByText(product.name, { exact: true }) });
20	  }
21	
22	  async open(): Promise<void> {
23	    await this.openRoute(UI_ROUTES.basket);
24	  }
25	
26	  async shouldSeePage(): Promise<void> {
27	    await this.shouldSeeTitle(UI_TEXT.basket.heading);
28	  }
29	
30	  async shouldSeeProductRow({ product, quantity }: BasketLine): Promise<void> {
31	    const row = this.rowOf(product);
32	    await expectVisible(row, `basket row of ${product.name}`);
33	    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
34	    await expectVisible(row.getByRole('cell', { name: product.price, exact: true }), `price ${product.price} of ${product.name}`);
35	  }
