46	    await expectVisible(this.page.getByText(UI_TEXT.basket.totalPrice(total), { exact: true }), `total ${total}`);
47	  }
48	
49	  /** Each click waits for the new quantity: a quick second click can be lost while the row is re-rendered. */
50	  async clickIncreaseQuantity(product: ShopProduct, times = 1): Promise<void> {
51	    for (let click = 0; click < times; click += 1) {
52	      const quantityBefore = await this.readQuantity(product);
53	      await this.clickRowIcon(product, UI_TEXT.basket.increaseIcon);
54	      await expect(async () => {
55	        expect(await this.readQuantity(product)).toBe(quantityBefore + 1);
56	      }).toPass({ timeout: UI_TIMEOUT });
57	    }
58	  }
59	
60	  /** One click without waiting: the quantity does not change when the click is refused by the limit. */
61	  async clickIncreaseQuantityOnce(product: ShopProduct): Promise<void> {
62	    await this.clickRowIcon(product, UI_TEXT.basket.increaseIcon);
63	  }
