73	  async clickCheckout(): Promise<void> {
74	    await this.checkoutButton.click();
75	  }
76	
77	  async shouldSeeCheckoutDisabled(): Promise<void> {
78	    await expectDisabled(this.checkoutButton, 'button Checkout is disabled');
79	  }
80	
81	  private async clickRowIcon(product: ShopProduct, icon: string): Promise<void> {
82	    await this.rowOf(product).locator(`button:has(svg[data-icon="${icon}"])`).click();
83	  }
84	
85	  private async readQuantity(product: ShopProduct): Promise<number> {
86	    const quantityCell = this.rowOf(product).getByRole('cell', { name: /^\d+$/ });
