1	import { encode } from 'z85';
2	
3	/**
4	 * Coupon codes of the shop: Z85 encoding of `<MMM><YY>-<NN>`, see test-cases/README.md.
5	 * The shop accepts a coupon only in the month that the coupon names. The month is taken
6	 * from the local time of the machine, the same as on the server (juice-shop-app.md, section 5).
7	 */
8	const COUPON_MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
9	const YEAR_DIGITS = 2;
10	const PERCENT_DIGITS = 2;
11	
12	export function buildCouponCode(month: Date, discountPercent: number): string {
13	  const monthName = COUPON_MONTHS[month.getMonth()];
14	  const year = String(month.getFullYear()).slice(-YEAR_DIGITS);
15	  const percent = String(discountPercent).padStart(PERCENT_DIGITS, '0');
16	  const text = `${monthName}${year}-${percent}`;
17	  const code = encode(text);
18	  if (code === null) {
19	    throw new Error(`Coupon text has a length that Z85 cannot encode: ${text}`);
20	  }
21	  return code;
22	}
23	
24	/** A coupon of the current month. It is valid. */
25	export function currentMonthCoupon(discountPercent: number): string {
26	  return buildCouponCode(new Date(), discountPercent);
27	}
28	
29	/** A coupon of the previous month. The shop rejects it as expired. */
30	export function previousMonthCoupon(discountPercent: number): string {
31	  const now = new Date();
32	  return buildCouponCode(new Date(now.getFullYear(), now.getMonth() - 1, 1), discountPercent);
33	}
