1	/**
2	 * Test data of a customer, prepared through the API before the UI steps.
3	 * Each function acts on one customer. The spec passes its `api` fixture and its `customer`.
4	 */
5	import type { ShopApi } from '@/core/api/shop-api';
6	import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
