31	    const row = this.rowOf(product);
32	    await expectVisible(row, `basket row of ${product.name}`);
33	    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
34	    await expectVisible(row.getByRole('cell', { name: product.price, exact: true }), `price ${product.price} of ${product.name}`);
