10	/** Creates a new normal customer account and returns it with a token and a basket. */
11	export async function createCustomer(api: ShopApi): Promise<Customer> {
12	  const credentials = buildCustomerCredentials();
13	  const id = await api.users.register(credentials);
14	  const session = await api.users.login(credentials);
15	  return { ...credentials, id, token: session.token, basketId: session.basketId };
16	}
17	
18	export async function addProductsToBasket(api: ShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
19	  for (const { product, quantity } of lines) {
20	    const productId = await api.products.findIdByName(product.name);
21	    await api.baskets.addProduct(customer, productId, quantity);
22	  }
23	}
24	
25	/** Saves the saved address and the saved card of the test cases. Returns the card id, the payment id. */
26	export async function saveAddressAndCard(api: ShopApi, customer: Customer): Promise<number> {
27	  await api.payments.addAddress(customer, SAVED_ADDRESS);
28	  return api.payments.addCard(customer, SAVED_CARD);
29	}
