31	/** The shop adds money to the wallet only with a saved card of the customer. */
32	export async function topUpWallet(api: ShopApi, customer: Customer, cardId: number, amount: number): Promise<void> {
33	  await api.payments.topUpWallet(customer, cardId, amount);
34	}
