async () => {
  const j = (r) => r.json();
  const email = 'probe3-' + Date.now() + '@example.test';
  const pw = 'Passw0rd!p3x';
  await fetch('/api/Users', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({email, password: pw, passwordRepeat: pw, securityQuestion:{id:1}, securityAnswer:'x'})});
  const l = await j(await fetch('/rest/user/login', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({email, password: pw})}));
  const tok = l.authentication.token, bid = l.authentication.bid;
  const A = {'Content-Type':'application/json', 'Authorization':'Bearer '+tok};
  await fetch('/api/BasketItems', {method:'POST', headers:A, body: JSON.stringify({ProductId:3, BasketId:String(bid), quantity:1})});
  await fetch('/api/Addresss', {method:'POST', headers:A, body: JSON.stringify({fullName:'Test Customer', mobileNum:501234567, zipCode:'01001', streetAddress:'1 Khreshchatyk Street', city:'Kyiv', state:'Kyiv', country:'Ukraine'})});
  const card = await j(await fetch('/api/Cards', {method:'POST', headers:A, body: JSON.stringify({fullName:'Test Customer', cardNum:4111111111111111, expMonth:12, expYear:2090})}));
  await fetch('/rest/wallet/balance', {method:'PUT', headers:A, body: JSON.stringify({balance:5, paymentId:String(card.data.id)})});
  await fetch('/rest/wallet/balance', {method:'PUT', headers:A, body: JSON.stringify({balance:3.99, paymentId:String(card.data.id)})});
  const w = await j(await fetch('/rest/wallet/balance', {headers:A}));
  localStorage.setItem('token', tok); sessionStorage.setItem('bid', String(bid));
  document.cookie = 'token=' + tok + '; path=/'; document.cookie = 'cookieconsent_status=dismiss; path=/'; document.cookie = 'language=en; path=/';
  return JSON.stringify({email, bid, wallet: w.data});
}

