import { expect, type Locator, type Page } from '@playwright/test';
import { DateHelper } from '@/utils/helpers/date-helper';

/** Used by page objects and helpers only. Specs call the `should*` methods of the page objects. */
export const UI_TIMEOUT = DateHelper.secondsToMs(15);

export async function expectVisible(locator: Locator, description: string): Promise<void> {
  await expect(locator, description).toBeVisible({ timeout: UI_TIMEOUT });
}

export async function expectHidden(locator: Locator, description: string): Promise<void> {
  await expect(locator, description).toBeHidden({ timeout: UI_TIMEOUT });
}

export async function expectText(locator: Locator, text: string, description: string): Promise<void> {
  await expect(locator, description).toHaveText(text, { timeout: UI_TIMEOUT });
}

export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
  await expect(locator, description).toContainText(text, { timeout: UI_TIMEOUT });
}

export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
  await expect(locator, description).toHaveCount(count, { timeout: UI_TIMEOUT });
}

export async function expectEnabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, description).toBeEnabled({ timeout: UI_TIMEOUT });
}

export async function expectDisabled(locator: Locator, description: string): Promise<void> {
  await expect(locator, description).toBeDisabled({ timeout: UI_TIMEOUT });
}

/** Checks the hash route of the page, given as in UI_ROUTES, for example `/#/login`. */
export async function expectUrlHash(page: Page, route: string, description: string): Promise<void> {
  const hashPrefix = route.slice(route.indexOf('#'));
  await expect(page, description).toHaveURL((url) => url.hash.startsWith(hashPrefix), { timeout: UI_TIMEOUT });
}

