const VISIBLE_DIGITS = 4;
const MASK_CHARACTER = '*';
const MASKED_DIGITS_COUNT = 12;

/** The last four digits of a card number, as the shop shows them. */
export function lastFourDigits(cardNumber: number): string {
  return String(cardNumber).slice(-VISIBLE_DIGITS);
}

/** The card number as the shop shows it in the list of saved cards, for example `************1111`. */
export function maskedCardNumber(cardNumber: number): string {
  return `${MASK_CHARACTER.repeat(MASKED_DIGITS_COUNT)}${lastFourDigits(cardNumber)}`;
}

