import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import type { ShopProduct } from '@/utils/types/shop-types';

/** The product list `/#/search`. A product card is an `article` with the name, the price and the button. */
export class ProductListPage extends BasePage {
  private readonly navbar: NavbarComponent;

  constructor(page: Page) {
    super(page);
    this.navbar = new NavbarComponent(page);
  }

  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.search);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlHash(this.page, UI_ROUTES.search, 'product list is open');
    await expectVisible(this.page.getByText(UI_TEXT.productList.heading, { exact: true }), 'title "All Products"');
  }

  async shouldSeeProduct(product: ShopProduct): Promise<void> {
    const card = this.productCard(product);
    await expectVisible(card, `product card of ${product.name}`);
    await expectVisible(card.getByText(product.price, { exact: true }), `price ${product.price} of ${product.name}`);
    await expectVisible(card.getByRole('button', { name: UI_TEXT.productList.addToBasketButton }), `button Add to Basket of ${product.name}`);
  }

  /** Clicks Add to Basket and waits until the basket counter grows. A quick second click is not lost this way. */
  async clickAddToBasket(product: ShopProduct): Promise<void> {
    const counterBefore = await this.navbar.readBasketCounter();
    await this.clickAddToBasketOnce(product);
    await expect(async () => {
      expect(await this.navbar.readBasketCounter()).toBe(counterBefore + 1);
    }).toPass({ timeout: UI_TIMEOUT });
  }

  /** One click without waiting. Use it when the shop refuses the click, so the counter does not change. */
  async clickAddToBasketOnce(product: ShopProduct): Promise<void> {
    await this.productCard(product).getByRole('button', { name: UI_TEXT.productList.addToBasketButton }).click();
  }

  private productCard(product: ShopProduct): Locator {
    return this.page.locator('article').filter({ has: this.page.getByText(product.name, { exact: true }) });
  }
}

