import type { Locator, Page } from '@playwright/test';
import { expectCount, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_TEXT } from '@/utils/constants/ui-texts';

/** The panel `Add a coupon` on the payment step. */
export class CouponPanelComponent {
  constructor(private readonly page: Page) {}

  private get panelButton(): Locator {
    return this.page.getByRole('button', { name: UI_TEXT.payment.couponPanel });
  }

  private get couponField(): Locator {
    return this.page.getByRole('textbox', { name: UI_TEXT.payment.couponField });
  }

  async shouldSeePanelButton(): Promise<void> {
    await expectVisible(this.panelButton, 'panel "Add a coupon"');
  }

  async open(): Promise<void> {
    await this.panelButton.click();
    await expectVisible(this.couponField, 'coupon field');
  }

  async fillCouponCode(code: string): Promise<void> {
    await this.couponField.fill(code);
  }

  async clickRedeem(): Promise<void> {
    await this.page.getByRole('button', { name: UI_TEXT.payment.redeemButton }).click();
  }

  async shouldSeeDiscountApplied(percent: number): Promise<void> {
    const message = UI_TEXT.payment.discountApplied(percent);
    await expectVisible(this.page.getByText(message, { exact: true }), `message "${message}"`);
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.payment.invalidCoupon, { exact: true }), 'error "Invalid coupon."');
  }

  async shouldNotSeeDiscountApplied(): Promise<void> {
    await expectCount(this.page.getByText(UI_TEXT.payment.discountPrefix), 0, 'no discount message');
  }
}

