import type { Locator } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectCount, expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTES } from '@/utils/constants/routes';
import { UI_TEXT } from '@/utils/constants/ui-texts';
import { escapeRegExp } from '@/utils/helpers/text-helper';
import type { ShopProduct } from '@/utils/types/shop-types';

export interface OrderedProduct {
  product: ShopProduct;
  quantity: number;
}

/**
 * The page `/#/order-history`. Each order is a block with `Order ID #<id>`, `Total Price <total>`,
 * `Bonus <points>` and a table of its products.
 */
export class OrderHistoryPage extends BasePage {
  async open(): Promise<void> {
    await this.openRoute(UI_ROUTES.orderHistory);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlHash(this.page, UI_ROUTES.orderHistory, 'order history page is open');
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.heading).first(), `title "${UI_TEXT.orderHistory.heading}"`);
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.noOrders, { exact: true }), 'message "You have not placed any orders yet."');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.page.getByText(UI_TEXT.orderHistory.orderIdLabel), count, `order count is ${count}`);
  }

  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
    const block = this.orderBlock(orderId);
    await expectVisible(block, `order ${orderId}`);
    await expectContainText(block, this.totalPriceLine(total), `total ${total} of order ${orderId}`);
  }

  /** The only order of the customer: its total and its bonus points. */
  async shouldSeeSingleOrder(total: string, bonusPoints: string): Promise<void> {
    const block = this.orderBlock();
    await expectVisible(block, 'the order block');
    await expectContainText(block, this.totalPriceLine(total), `total ${total} of the order`);
    await expectContainText(block, new RegExp(`${UI_TEXT.orderHistory.bonus}\\s*${bonusPoints}(?!\\d)`), `bonus points ${bonusPoints} of the order`);
  }

  async shouldSeeOrderProduct(orderId: string, { product, quantity }: OrderedProduct): Promise<void> {
    const row = this.orderBlock(orderId)
      .getByRole('row')
      .filter({ has: this.page.getByRole('cell', { name: product.name, exact: true }) });
    await expectVisible(row, `order row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
  }

  private totalPriceLine(total: string): RegExp {
    return new RegExp(`${escapeRegExp(UI_TEXT.orderHistory.totalPrice(total))}`.replace(/\\ /g, '\\s*'));
  }

  /** The block of an order: the innermost block with a table of products, and the order ID when given. */
  private orderBlock(orderId?: string): Locator {
    const blocksWithTable = this.page.locator('div').filter({ has: this.page.getByRole('table') });
    return orderId ? blocksWithTable.filter({ hasText: orderId }).last() : blocksWithTable.last();
  }
}

