    await expectContainText(block, this.totalPriceLine(total), `total ${total} of the order`);
    await expectContainText(block, new RegExp(`${UI_TEXT.orderHistory.bonus}\\s*${bonusPoints}(?!\\d)`), `bonus points ${bonusPoints} of the order`);
  }

  async shouldSeeOrderProduct(orderId: string, { product, quantity }: OrderedProduct): Promise<void> {
    const row = this.orderBlock(orderId)
      .getByRole('row')
      .filter({ has: this.page.getByRole('cell', { name: product.name, exact: true }) });
    await expectVisible(row, `order row of ${product.name}`);
    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
  }

  private totalPriceLine(total: string): RegExp {
    return new RegExp(`${escapeRegExp(UI_TEXT.orderHistory.totalPrice(total))}`.replace(/\\ /g, '\\s*'));
  }

  /** The block of an order: the innermost block with a table of products, and the order ID when given. */
  private orderBlock(orderId?: string): Locator {
    const blocksWithTable = this.page.locator('div').filter({ has: this.page.getByRole('table') });
    return orderId ? blocksWithTable.filter({ hasText: orderId }).last() : blocksWithTable.last();
  }
}

