1	import type { Locator } from '@playwright/test';
2	import { BasePage } from '@/page-objects/base-page';
3	import { expectContainText, expectCount, expectUrlHash, expectVisible } from '@/utils/assertions/ui-assertions';
4	import { UI_ROUTES } from '@/utils/constants/routes';
5	import { UI_TEXT } from '@/utils/constants/ui-texts';
6	import { escapeRegExp } from '@/utils/helpers/text-helper';
7	import type { ShopProduct } from '@/utils/types/shop-types';
8	
9	export interface OrderedProduct {
10	  product: ShopProduct;
11	  quantity: number;
12	}
13	
14	/**
15	 * The page `/#/order-history`. Each order is a block with `Order ID #<id>`, `Total Price <total>`,
16	 * `Bonus <points>` and a table of its products.
17	 */
18	export class OrderHistoryPage extends BasePage {
19	  async open(): Promise<void> {
20	    await this.openRoute(UI_ROUTES.orderHistory);
21	  }
22	
23	  async shouldSeePage(): Promise<void> {
24	    await expectUrlHash(this.page, UI_ROUTES.orderHistory, 'order history page is open');
25	    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.heading).first(), `title "${UI_TEXT.orderHistory.heading}"`);
26	  }
27	
28	  async shouldSeeNoOrders(): Promise<void> {
29	    await expectVisible(this.page.getByText(UI_TEXT.orderHistory.noOrders, { exact: true }), 'message "You have not placed any orders yet."');
30	  }
31	
32	  async shouldSeeOrderCount(count: number): Promise<void> {
33	    await expectCount(this.page.getByText(UI_TEXT.orderHistory.orderIdLabel), count, `order count is ${count}`);
34	  }
35	
36	  async shouldSeeOrder(orderId: string, total: string): Promise<void> {
37	    const block = this.orderBlock(orderId);
38	    await expectVisible(block, `order ${orderId}`);
39	    await expectContainText(block, this.totalPriceLine(total), `total ${total} of order ${orderId}`);
40	  }
41	
42	  /** The only order of the customer: its total and its bonus points. */
43	  async shouldSeeSingleOrder(total: string, bonusPoints: string): Promise<void> {
44	    const block = this.orderBlock();
45	    await expectVisible(block, 'the order block');
46	    await expectContainText(block, this.totalPriceLine(total), `total ${total} of the order`);
47	    await expectContainText(block, new RegExp(`${UI_TEXT.orderHistory.bonus}\\s*${bonusPoints}(?!\\d)`), `bonus points ${bonusPoints} of the order`);
48	  }
49	
50	  async shouldSeeOrderProduct(orderId: string, { product, quantity }: OrderedProduct): Promise<void> {
51	    const row = this.orderBlock(orderId)
52	      .getByRole('row')
53	      .filter({ has: this.page.getByRole('cell', { name: product.name, exact: true }) });
54	    await expectVisible(row, `order row of ${product.name}`);
55	    await expectVisible(row.getByRole('cell', { name: String(quantity), exact: true }), `quantity ${quantity} of ${product.name}`);
56	  }
57	
58	  /** The label and the amount can be separated by spaces, or by nothing, in the DOM text. */
59	  private totalPriceLine(total: string): RegExp {
60	    return new RegExp(`${escapeRegExp(UI_TEXT.orderHistory.totalLabel)}\\s*${escapeRegExp(total)}`);
61	  }
62	
63	  /** The block of an order: the innermost block with a table of products, and the order ID when given. */
64	  private orderBlock(orderId?: string): Locator {
65	    const blocksWithTable = this.page.locator('div').filter({ has: this.page.getByRole('table') });
66	    return orderId ? blocksWithTable.filter({ hasText: orderId }).last() : blocksWithTable.last();
67	  }
68	}
