1	const VISIBLE_DIGITS = 4;
2	const MASK_CHARACTER = '*';
3	const MASKED_DIGITS_COUNT = 12;
4	
5	/** The last four digits of a card number, as the shop shows them. */
6	export function lastFourDigits(cardNumber: number): string {
7	  return String(cardNumber).slice(-VISIBLE_DIGITS);
8	}
9	
10	/** The card number as the shop shows it in the list of saved cards, for example `************1111`. */
11	export function maskedCardNumber(cardNumber: number): string {
12	  return `${MASK_CHARACTER.repeat(MASKED_DIGITS_COUNT)}${lastFourDigits(cardNumber)}`;
13	}
